#include <observation/health/health_monitor.hpp>
#include <cmath>
namespace rebuntu::health { void HealthMonitor::record(Sample s){auto&v=samples_[s.metric];v.push_back(std::move(s));if(v.size()>256)v.erase(v.begin(),v.begin()+static_cast<long>(v.size()-256));} Trend HealthMonitor::trend(const std::string&m)const{Trend t;auto i=samples_.find(m);if(i==samples_.end()||i->second.empty())return t;auto&v=i->second;t.latest=v.back().value;for(auto&s:v)t.mean+=s.value;t.mean/=v.size();if(v.size()>1)t.slope=(v.back().value-v.front().value)/double(v.size()-1);double var=0;for(auto&s:v)var+=(s.value-t.mean)*(s.value-t.mean);var/=v.size();t.anomalous=v.size()>3&&std::sqrt(var)>0&&std::abs(t.latest-t.mean)>2.5*std::sqrt(var);return t;} std::vector<std::string> HealthMonitor::degraded()const{std::vector<std::string>o;for(auto&[k,v]:samples_)if(trend(k).anomalous)o.push_back(k);return o;} }
